package main

import "fmt"

type Point struct{ X, Y int }

// Returned by value: the struct can stay on the caller's stack.
func onStack() Point {
	p := Point{X: 1, Y: 2}
	return p // does NOT escape
}

// Returns a pointer: the value must outlive this frame, so it escapes.
func onHeap() *Point {
	p := Point{X: 3, Y: 4}
	return &p // escapes to heap
}

func main() {
	a := onStack()
	b := onHeap()
	fmt.Println(a, *b)
}

