package main

import (
	"bytes"
	"fmt"
	"sync"
)

// New is called only when the pool is empty.
var bufPool = sync.Pool{New: func() any { return new(bytes.Buffer) }}

func greet(name string) string {
	b := bufPool.Get().(*bytes.Buffer) // reuse if available
	defer bufPool.Put(b)               // return for the next caller
	b.Reset()                          // critical: clear stale state
	b.WriteString("hello, ")
	b.WriteString(name)
	return b.String() // copies out before Put recycles the buffer
}

func main() {
	fmt.Println(greet("ada"))
	fmt.Println(greet("go"))
}

