func (l *Logger) Debugf(format string, args ...any) {
	// Cheap check first: if Debug is off, return before any formatting
	// or interface boxing of args occurs.
	if l.level > DebugLevel {
		return
	}
	l.write(fmt.Sprintf(format, args...))
}

// Hot-path callers can guard too, so args aren't even evaluated/boxed:
for _, r := range requests {
	if log.Enabled(DebugLevel) {
		log.Debugf("handling %d", r.ID)
	}
}

func Sum(line []byte) int {
	total, cur := 0, 0
	for _, c := range line {
		if c == ',' {
			total += cur // commit the finished number
			cur = 0
			continue
		}
		cur = cur*10 + int(c-'0') // shift in the next digit
	}
	return total + cur // commit the last number
}
